namespace ghidra.file.formats.android.vdex;





using ghidra.app.util.bin;
using ghidra.app.util.bin;
using ghidra.program.model.data;
using ghidra.util.exception;

public class VdexStringTable : StructConverter {

	private int stringCount;//note only 1 byte in size
	private List<string> strings = new();

	public VdexStringTable(BinaryReader reader)
    {
		stringCount = Byte.toUnsignedInt(reader.readNextByte());
		for (int i = 0; i < stringCount; ++i) {
			strings.add(reader.readNextAsciiString());
		}
	}

	public int getStringCount() {
		return stringCount;
	}

	public List<string> getStrings() {
		return strings;
	}

	public int getSize() {
		int size = 1;
		for (int i = 0; i < stringCount; ++i) {
			string string = strings.get(i);
			size += string.length() + 1;
		}
		return size;
	}

	/* @Override */
	public DataType toDataType()
    {
		Structure structure =
			new StructureDataType(typeof(VdexStringTable).getSimpleName() + "_" + stringCount, 0);
		structure.add(BYTE, "stringCount", null);
		for (int i = 0; i < stringCount; ++i) {
			string string = strings.get(i);
			structure.add(STRING, string.length() + 1, "string_" + i, null);
		}
		structure.setCategoryPath(new CategoryPath("/vdex"));
		return structure;
	}
}
